ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS cnpj text, ADD COLUMN IF NOT EXISTS telefone_publico text, ADD COLUMN IF NOT EXISTS endereco text;
ALTER TABLE public.produtos ADD COLUMN IF NOT EXISTS imagem_path text, ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true;
ALTER TABLE public.pedidos ADD COLUMN IF NOT EXISTS mensagem_proposta text;
ALTER TABLE public.pedidos DROP CONSTRAINT IF EXISTS pedidos_status_check;
ALTER TABLE public.pedidos ADD CONSTRAINT pedidos_status_check CHECK(status IN ('Em negociação','Contraproposta','Aguardando pagamento','Aguardando envio','Pago','Enviado','Recusado'));
CREATE TABLE public.buscas_usuario(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, consulta text NOT NULL CHECK(length(btrim(consulta)) BETWEEN 3 AND 600), pesquisado_em timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,consulta));
GRANT SELECT,INSERT,UPDATE ON public.buscas_usuario TO authenticated;
GRANT ALL ON public.buscas_usuario TO service_role;
ALTER TABLE public.buscas_usuario ENABLE ROW LEVEL SECURITY;
CREATE POLICY "search own" ON public.buscas_usuario FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.fornecedores_favoritos(comprador_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, fornecedor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, criado_em timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(comprador_id,fornecedor_id), CHECK(comprador_id<>fornecedor_id));
GRANT SELECT,INSERT,DELETE ON public.fornecedores_favoritos TO authenticated;
GRANT ALL ON public.fornecedores_favoritos TO service_role;
ALTER TABLE public.fornecedores_favoritos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "supplier favorites own" ON public.fornecedores_favoritos FOR ALL TO authenticated USING(comprador_id=auth.uid()) WITH CHECK(comprador_id=auth.uid() AND public.meu_tipo()='e' AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=fornecedor_id AND 'f'=ANY(p.tipos)));
CREATE TABLE public.notificacoes(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,tipo text NOT NULL,titulo text NOT NULL,texto text NOT NULL,pedido_id bigint REFERENCES public.pedidos(id) ON DELETE SET NULL,mensagem_id bigint REFERENCES public.mensagens(id) ON DELETE SET NULL,avaliacao_id bigint REFERENCES public.avaliacoes(id) ON DELETE SET NULL,criado_em timestamptz NOT NULL DEFAULT now(),lida_em timestamptz);
GRANT SELECT ON public.notificacoes TO authenticated;
GRANT UPDATE(lida_em) ON public.notificacoes TO authenticated;
GRANT ALL ON public.notificacoes TO service_role;
ALTER TABLE public.notificacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "notifications read own" ON public.notificacoes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "notifications mark own" ON public.notificacoes FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX notificacoes_user_created_idx ON public.notificacoes(user_id,criado_em DESC);
CREATE INDEX buscas_usuario_recent_idx ON public.buscas_usuario(user_id,pesquisado_em DESC);
CREATE OR REPLACE FUNCTION public.notificar_nova_mensagem() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notificacoes(user_id,tipo,titulo,texto,mensagem_id) VALUES(NEW.para_id,'nova_mensagem','Nova mensagem',NEW.texto,NEW.id); RETURN NEW; END $$;
CREATE TRIGGER trg_notificar_nova_mensagem AFTER INSERT ON public.mensagens FOR EACH ROW EXECUTE FUNCTION public.notificar_nova_mensagem();
CREATE OR REPLACE FUNCTION public.notificar_nova_avaliacao() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notificacoes(user_id,tipo,titulo,texto,avaliacao_id) VALUES(NEW.fornecedor_id,'nova_avaliacao','Nova avaliação','Você recebeu uma nova avaliação.',NEW.id); RETURN NEW; END $$;
CREATE TRIGGER trg_notificar_nova_avaliacao AFTER INSERT ON public.avaliacoes FOR EACH ROW EXECUTE FUNCTION public.notificar_nova_avaliacao();
CREATE OR REPLACE FUNCTION public.notificar_eventos_pedido() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE supplier uuid; recipient uuid; event text; heading text; product_name text; BEGIN SELECT fornecedor_id,nome INTO supplier,product_name FROM public.produtos WHERE id=NEW.produto_id; IF TG_OP='INSERT' THEN INSERT INTO public.notificacoes(user_id,tipo,titulo,texto,pedido_id) VALUES(supplier,'nova_proposta','Nova proposta','Você recebeu uma proposta para '||product_name||'.',NEW.id); ELSIF NEW.status IS DISTINCT FROM OLD.status THEN recipient:=CASE WHEN auth.uid()=NEW.empresario_id THEN supplier ELSE NEW.empresario_id END; event:=CASE NEW.status WHEN 'Contraproposta' THEN 'contraproposta' WHEN 'Recusado' THEN 'proposta_recusada' ELSE 'proposta_aceita' END; heading:='Pedido atualizado'; INSERT INTO public.notificacoes(user_id,tipo,titulo,texto,pedido_id) VALUES(recipient,event,heading,product_name||': '||NEW.status,NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_notificar_eventos_pedido AFTER INSERT OR UPDATE OF status ON public.pedidos FOR EACH ROW EXECUTE FUNCTION public.notificar_eventos_pedido();
CREATE OR REPLACE FUNCTION public.criar_proposta(_produto_id bigint,_quantidade integer,_preco numeric,_mensagem text) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE supplier uuid; minimum_qty integer; order_id bigint; BEGIN IF auth.uid() IS NULL OR public.meu_tipo() IS DISTINCT FROM 'e' OR _quantidade IS NULL OR _quantidade<=0 OR _preco IS NULL OR _preco<=0 OR _mensagem IS NULL OR length(trim(_mensagem)) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Informe quantidade, valor e mensagem válidos'; END IF; SELECT fornecedor_id,qtd_min INTO supplier,minimum_qty FROM public.produtos WHERE id=_produto_id AND ativo; IF NOT FOUND OR supplier=auth.uid() THEN RAISE EXCEPTION 'Produto indisponível para esta conta'; END IF; IF _quantidade<minimum_qty THEN RAISE EXCEPTION 'A quantidade precisa respeitar o mínimo do produto'; END IF; INSERT INTO public.pedidos(produto_id,empresario_id,qtd,preco_unitario,comprador_aceitou,fornecedor_aceitou,mensagem_proposta) VALUES(_produto_id,auth.uid(),_quantidade,_preco,true,false,trim(_mensagem)) RETURNING id INTO order_id; INSERT INTO public.mensagens(de_id,para_id,texto) VALUES(auth.uid(),supplier,'Nova proposta: '||trim(_mensagem)); RETURN order_id; END $$;
REVOKE ALL ON FUNCTION public.criar_proposta(bigint,integer,numeric,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.criar_proposta(bigint,integer,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.contrapropor_negociacao(_id bigint,_quantidade integer,_preco numeric,_mensagem text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE buyer uuid; supplier uuid; minimum_qty integer; BEGIN IF auth.uid() IS NULL OR _quantidade IS NULL OR _quantidade<=0 OR _preco IS NULL OR _preco<=0 OR _mensagem IS NULL OR length(trim(_mensagem)) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Informe quantidade, preço e mensagem válidos'; END IF; SELECT o.empresario_id,p.fornecedor_id,p.qtd_min INTO buyer,supplier,minimum_qty FROM public.pedidos o JOIN public.produtos p ON p.id=o.produto_id WHERE o.id=_id AND o.status='Em negociação'; IF NOT FOUND OR supplier IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Negociação indisponível para esta conta'; END IF; IF _quantidade<minimum_qty THEN RAISE EXCEPTION 'A quantidade precisa respeitar o mínimo do produto'; END IF; UPDATE public.pedidos SET qtd=_quantidade,preco_unitario=_preco,status='Contraproposta',comprador_aceitou=false,fornecedor_aceitou=true,mensagem_proposta=trim(_mensagem) WHERE id=_id; INSERT INTO public.mensagens(de_id,para_id,texto) VALUES(auth.uid(),buyer,'Contraproposta: '||trim(_mensagem)); END $$;
REVOKE ALL ON FUNCTION public.contrapropor_negociacao(bigint,integer,numeric,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.contrapropor_negociacao(bigint,integer,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.responder_contraproposta(_id bigint,_aceitar boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _aceitar IS NULL THEN RAISE EXCEPTION 'É necessário entrar na conta e escolher uma resposta'; END IF; UPDATE public.pedidos SET status=CASE WHEN _aceitar THEN 'Aguardando pagamento' ELSE 'Recusado' END,comprador_aceitou=_aceitar,fornecedor_aceitou=_aceitar WHERE id=_id AND empresario_id=auth.uid() AND public.meu_tipo()='e' AND status='Contraproposta'; IF NOT FOUND THEN RAISE EXCEPTION 'Contraproposta indisponível para esta conta'; END IF; END $$;
REVOKE ALL ON FUNCTION public.responder_contraproposta(bigint,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.responder_contraproposta(bigint,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.trocar_tipo_perfil(_tipo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _tipo IS NULL OR _tipo NOT IN ('f','e') THEN RAISE EXCEPTION 'Tipo de perfil inválido'; END IF; UPDATE public.profiles SET tipo=_tipo WHERE id=auth.uid() AND _tipo=ANY(tipos); IF NOT FOUND THEN RAISE EXCEPTION 'Este tipo de perfil não está habilitado para a conta'; END IF; END $$;
REVOKE ALL ON FUNCTION public.trocar_tipo_perfil(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.trocar_tipo_perfil(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.resolve_login_email(_phone text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.email FROM public.profiles p JOIN public.profiles_private pp ON pp.id=p.id WHERE CASE WHEN length(regexp_replace(pp.telefone,'[^0-9]','','g')) IN(10,11) THEN '55'||regexp_replace(pp.telefone,'[^0-9]','','g') ELSE regexp_replace(pp.telefone,'[^0-9]','','g') END = CASE WHEN length(regexp_replace(_phone,'[^0-9]','','g')) IN(10,11) THEN '55'||regexp_replace(_phone,'[^0-9]','','g') ELSE regexp_replace(_phone,'[^0-9]','','g') END AND length(regexp_replace(_phone,'[^0-9]','','g')) BETWEEN 10 AND 13 LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.resolve_login_email(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_login_email(text) TO anon,authenticated;
NOTIFY pgrst,'reload schema';